  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1220;
      --panel: #111827;
      --panel-2: #0f172a;
      --border: #243041;
      --text: #e5eefb;
      --muted: #93a4bd;
      --accent: #7c9cff;
      --accent-strong: #9fb4ff;
      --error: #ff7b7b;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.38);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
        linear-gradient(180deg, #07101d 0%, #0b1220 100%);
      color: var(--text);
    }

    .card {
      width: min(100%, 640px);
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.96));
      border: 1px solid rgba(124, 156, 255, 0.15);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.6rem, 2vw, 2.2rem);
      line-height: 1.1;
    }

    p {
      margin: 0 0 26px;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      color: var(--text);
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(9, 14, 25, 0.9);
      color: var(--text);
      padding: 14px 15px;
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #6f7f99;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.16);
    }

    .helper-text,
    .error-text {
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--error);
      min-height: 1.3em;
    }

    .form-field.invalid input {
      border-color: rgba(255, 123, 123, 0.9);
      box-shadow: 0 0 0 4px rgba(255, 123, 123, 0.12);
    }

    button {
      margin-top: 6px;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      background: linear-gradient(135deg, var(--accent), #5f7cff);
      color: white;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(95, 124, 255, 0.28);
      transition: transform 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(159, 180, 255, 0.55);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.4em;
      color: #a8ffcb;
      font-size: 0.95rem;
      font-weight: 600;
    }
  </style>
</head>
<body>
  <main class="card">
    <h1>Contact Support</h1>
    <p>Send a message and our team will follow up by email or phone if needed.</p>

    <form id="support-form" novalidate>
      <div class="form-field" id="name-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" aria-describedby="full-name-error" />
        <div class="error-text" id="full-name-error" aria-live="polite"></div>
      </div>

      <div class="form-field" id="email-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" autocomplete="email" required placeholder="jane@example.com" aria-describedby="email-error" />
        <div class="error-text" id="email-error" aria-live="polite"></div>
      </div>

      <div class="form-field" id="phone-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" aria-describedby="phone-helper phone-error" />
        <div class="helper-text" id="phone-helper">Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.</div>
        <div class="error-text" id="phone-error" aria-live="polite"></div>
      </div>

      <button type="submit">Submit request</button>
      <div class="status" id="form-status" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusEl = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        field: document.getElementById('name-field'),
        error: document.getElementById('full-name-error'),
        validate: (value) => {
          if (!value.trim()) return 'Full name is required.';
          return '';
        }
      },
      email: {
        input: document.getElementById('email-address'),
        field: document.getElementById('email-field'),
        error: document.getElementById('email-error'),
        validate: (value) => {
          if (!value.trim()) return 'Email address is required.';
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return 'Enter a valid email address.';
          }
          return '';
        }
      },
      phone: {
        input: document.getElementById('phone-number'),
        field: document.getElementById('phone-field'),
        error: document.getElementById('phone-error'),
        validate: (value) => {
          const trimmed = value.trim();
          if (!trimmed) return '';
          if (!/^[+()\-.\s\d]{7,}$/.test(trimmed)) {
            return 'Enter a valid phone number format.';
          }
          return '';
        }
      }
    };

    function setFieldState({ field, error, input }, message) {
      field.classList.toggle('invalid', Boolean(message));
      error.textContent = message;
      input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(name) {
      const entry = fields[name];
      const message = entry.validate(entry.input.value);
      setFieldState(entry, message);
      return !message;
    }

    Object.entries(fields).forEach(([name, entry]) => {
      entry.input.addEventListener('blur', () => validateField(name));
      entry.input.addEventListener('input', () => {
        if (entry.error.textContent) validateField(name);
        statusEl.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      const isValid = Object.keys(fields).every(validateField);

      if (!isValid) {
        statusEl.textContent = '';
        return;
      }

      statusEl.textContent = 'Your request is ready to send.';
      form.reset();
      Object.values(fields).forEach((entry) => setFieldState(entry, ''));
    });
  </script>
</body>
</html>
